namespace sv_1a635c9018024d0cacfaabdb4987a19d.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit (user session).
/// Each user gets their own instance, so one manager's selection never affects another's.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    /// <summary>
    /// Fired whenever the selected warehouse changes. All subscribed components should re-render.
    /// </summary>
    public event Action? OnWarehouseChanged;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A — Downtown"),
        ("WH-002", "Warehouse B — Airport"),
        ("WH-003", "Warehouse C — Harbor"),
    ];

    public void Dispose()
    {
        OnWarehouseChanged = null;
    }
}

namespace sv_1a635c9018024d0cacfaabdb4987a19d.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and coordinates polling notifications
/// across all subscribed components within a single user circuit.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private static readonly Random _random = Random.Shared;

    private int _lastAlertCount;

    public int LastAlertCount => _lastAlertCount;

    /// <summary>
    /// Fired when new alert data is available. All subscribed components update simultaneously.
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query for items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by the polling component to publish new data to all subscribers.
    /// </summary>
    public void PublishAlertCount(int count)
    {
        _lastAlertCount = count;
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        OnAlertCountChanged = null;
    }
}

