@using sv_1a635c9018024d0cacfaabdb4987a19d.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label mb-1 text-white small">Current Warehouse</label>
    <select class="form-select form-select-sm" @onchange="OnSelectionChanged" value="@WarehouseState.CurrentWarehouseId">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnSelectionChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    // Re-render if another component somehow changes the warehouse
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= StateHasChanged;
    }
}

@using sv_1a635c9018024d0cacfaabdb4987a19d.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<span class="alert-badge @(AlertService.LastAlertCount > 0 ? "has-alerts" : "")">
    @if (AlertService.LastAlertCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@AlertService.LastAlertCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnAlertDataChanged;
    }

    private void OnAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnAlertDataChanged;
    }
}

@page "/dashboard"
@using sv_1a635c9018024d0cacfaabdb4987a19d.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h3>Warehouse Dashboard</h3>

<div class="card mb-3">
    <div class="card-body">
        <h5 class="card-title">
            Currently viewing: @GetWarehouseName()
        </h5>
        <p class="card-text">
            Warehouse ID: <code>@WarehouseState.CurrentWarehouseId</code>
        </p>
    </div>
</div>

<div class="card mb-3">
    <div class="card-body">
        <h5 class="card-title">
            <span class="bi bi-exclamation-triangle-fill text-warning" aria-hidden="true"></span>
            Low-Stock Alerts
        </h5>
        <p class="card-text fs-2">
            @if (_alertCount.HasValue)
            {
                <span class="@(_alertCount > 5 ? "text-danger" : "text-success")">
                    @_alertCount items below minimum level
                </span>
            }
            else
            {
