+    private int? _alertCount;
+    private DateTime? _lastUpdate;
+    private CancellationTokenSource? _cts;
+
+    protected override void OnInitialized()
+    {
+        WarehouseState.OnWarehouseChanged += OnWarehouseChanged;
+        AlertService.OnAlertCountChanged += OnAlertDataChanged;
+    }
+
+    protected override async Task OnAfterRenderAsync(bool firstRender)
+    {
+        if (firstRender)
+        {
+            // Start polling when dashboard becomes visible
+            _cts = new CancellationTokenSource();
+            await PollAlerts();
+            _ = StartPollingLoop(_cts.Token);
+        }
+    }
+
+    private async Task StartPollingLoop(CancellationToken ct)
+    {
+        while (!ct.IsCancellationRequested)
+        {
+            try
+            {
+                await Task.Delay(TimeSpan.FromSeconds(10), ct);
+                await PollAlerts();
+            }
+            catch (OperationCanceledException)
+            {
+                break;
+            }
+        }
+    }
+
+    private async Task PollAlerts()
+    {
+        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
+        _alertCount = count;
+        _lastUpdate = DateTime.Now;
+
+        // Publish to ALL subscribers (sidebar badge, other components)
+        AlertService.PublishAlertCount(count);
+
+        await InvokeAsync(StateHasChanged);
+    }
+
+    private void OnWarehouseChanged()
+    {
+        // Immediately re-poll when warehouse changes
+        _ = InvokeAsync(async () =>
+        {
+            await PollAlerts();
+        });
+    }
+
+    private void OnAlertDataChanged()
+    {
+        _alertCount = AlertService.LastAlertCount;
+        _lastUpdate = DateTime.Now;
+        InvokeAsync(StateHasChanged);
+    }
+
+    private string GetWarehouseName()
+    {
+        return WarehouseStateService.AvailableWarehouses
+            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name ?? "Unknown";
+    }
+
+    public void Dispose()
+    {
+        // Stop polling when user navigates away from dashboard
+        _cts?.Cancel();
+        _cts?.Dispose();
+        WarehouseState.OnWarehouseChanged -= OnWarehouseChanged;
+        AlertService.OnAlertCountChanged -= OnAlertDataChanged;
+    }
+}
